export const PRESETS = {
  default: '🤖',
  hacker1: '💀',
  hacker2: '🐱',
  hacker3: '👾',
  hacker4: '🕵️',
  hacker5: '🦊',
  hacker6: '🐉',
};

// Dynamically resolve backend URL — works for localhost AND public domains
const getBaseURL = () => {
  if (process.env.NODE_ENV === 'production') {
    // In production build, frontend and backend are on the same origin
    return window.location.origin;
  }
  // In development, backend runs on 5000
  return 'http://localhost:5000';
};

export const getAvatarDisplay = (user) => {
  if (user?.avatar_type === 'upload' && user?.avatar_url) {
    return {
      type: 'img',
      src: `${getBaseURL()}${user.avatar_url}`,
    };
  }
  if (user?.avatar_type === 'preset' && user?.avatar_preset) {
    return {
      type: 'emoji',
      emoji: PRESETS[user.avatar_preset] || '🤖',
    };
  }
  return { type: 'emoji', emoji: '🤖' };
};
